from pathlib import Path
from html import escape
P=Path(__file__).parent/'public'
TEAM_SOURCE='https://ftc-events.firstinspires.org/team/5214'
seasons=[('2026–27','BIOBUZZ','/seasons/biobuzz/'),('2025–26','DECODE','/seasons/decode/'),('2024–25','INTO THE DEEP','https://ftc-events.firstinspires.org/2024/team/5214'),('2023–24','CENTERSTAGE','https://ftc-events.firstinspires.org/2023/team/5214'),('2022–23','POWERPLAY','https://ftc-events.firstinspires.org/2022/team/5214'),('2021–22','FREIGHT FRENZY','https://ftc-events.firstinspires.org/2021/team/5214'),('2020–21','ULTIMATE GOAL','https://ftc-events.firstinspires.org/2020/team/5214'),('2019–20','SKYSTONE','https://ftc-events.firstinspires.org/2019/team/5214')]
arrow='<svg viewBox="0 0 18 18" fill="none" aria-hidden="true"><path d="M3 9h11m-5-5 5 5-5 5" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/></svg>'
arrow_diag='<svg viewBox="0 0 18 18" fill="none" aria-hidden="true"><path d="M4.5 13.5 13.5 4.5M5.5 4.5h8v8" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/></svg>'
logo='''<svg class="sunmark" viewBox="0 0 64 64" fill="none" aria-hidden="true"><circle cx="32" cy="32" r="14.5" fill="#E9A64A"/><circle cx="32" cy="32" r="7" fill="#F8E3B6"/><path d="M32 4v8M32 52v8M4 32h8M52 32h8M12.2 12.2l5.7 5.7m28.2 28.2 5.7 5.7m0-39.6-5.7 5.7M17.9 46.1l-5.7 5.7" stroke="#C85C3F" stroke-width="4" stroke-linecap="round"/></svg>'''

def link(path,label,kind='light',target=False):
    return f'<a class="button button--{kind}" href="{path}" {"target=\"_blank\" rel=\"noopener noreferrer\"" if target else ""}>{label}<span class="button-arrow">{arrow}</span></a>'

def header(active):
    navs=[('Home','/','home'),('About','/about/','about'),('Our team','/team/','team'),('Outreach','/outreach/','outreach')]
    links=''.join(f'<a class="nav-link {"is-active" if active==key else ""}" href="{url}" {"aria-current=\"page\"" if active==key else ""}>{title}</a>' for title,url,key in navs)
    season_links=''.join(f'<a href="{url}" {"target=\"_blank\" rel=\"noopener noreferrer\"" if url.startswith("http") else ""}><span>{year}</span><strong>{name}</strong></a>' for year,name,url in seasons)
    return f'''<header class="site-header" id="site-header"><div class="header-shell container">
      <a href="/" class="brand" aria-label="Helios team 5214, home">{logo}<span class="brand-copy"><strong>HELIOS<span class="brand-period">.</span></strong><small>FTC TEAM 5214</small></span></a>
      <button class="menu-toggle" aria-label="Open navigation" aria-expanded="false" aria-controls="primary-nav"><span></span><span></span><span></span></button>
      <nav class="main-nav" id="primary-nav" aria-label="Main navigation">{links}
        <details class="season-menu"><summary class="nav-link {"is-active" if active=='seasons' else ''}">Seasons <svg viewBox="0 0 12 12" width="13" height="13" aria-hidden="true"><path d="m2.5 4.5 3.5 3.5 3.5-3.5" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg></summary><div class="season-dropdown"><div class="dropdown-heading">SEASONS PLAYED</div>{season_links}<a class="view-all" href="/seasons/">View all seasons {arrow}</a></div></details>
        <a class="nav-contact {"is-active" if active=='contact' else ''}" href="/contact/">Contact {arrow_diag}</a>
      </nav></div></header>'''

def footer():
    return f'''<footer class="site-footer"><div class="container footer-top"><div><a href="/" class="footer-brand">{logo}<span>HELIOS<span class="brand-period">.</span></span></a><p>Ideas in motion. Since 2010.<br>FIRST Tech Challenge · Team 5214</p></div><div class="footer-links"><div><span class="footer-label">EXPLORE</span><a href="/about/">About</a><a href="/team/">Our team</a><a href="/outreach/">Outreach</a><a href="/seasons/">Seasons</a></div><div><span class="footer-label">CONNECT</span><a href="/contact/">Contact us</a><a href="mailto:5214.helios@gmail.com">Email the team</a><a href="{TEAM_SOURCE}" target="_blank" rel="noopener noreferrer">Official FIRST profile {arrow_diag}</a></div></div></div><div class="container footer-bottom"><span>© <span data-year>2026</span> Helios · FTC Team 5214</span><span>Made with purpose in Dublin, California.</span></div></footer>'''

def page(title,desc,active,content,path='/'):
    html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#F9F7F2"><meta name="description" content="{escape(desc,quote=True)}"><meta property="og:type" content="website"><meta property="og:title" content="{escape(title,quote=True)} | Helios · FTC 5214"><meta property="og:description" content="{escape(desc,quote=True)}"><meta property="og:image" content="/assets/social-card.svg"><title>{escape(title)} | Helios · FTC 5214</title><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;450;500;550;600;650;700;750;800&family=IBM+Plex+Mono:wght@400;500;600&display=swap" rel="stylesheet"><link rel="stylesheet" href="/assets/styles.css"><script src="/assets/main.js" defer></script></head><body><a class="skip-link" href="#main">Skip to content</a>{header(active)}<main id="main">{content}</main>{footer()}</body></html>'''
    dest=P/path.lstrip('/')/'index.html' if path!='/' else P/'index.html'
    dest.parent.mkdir(parents=True,exist_ok=True)
    dest.write_text(html,encoding='utf-8')

def eyebrow(txt):return f'<span class="eyebrow"><span class="eyebrow-dot"></span>{txt}</span>'

def section_intro(kicker,title,sub=''):
    return f'<div class="section-header">{eyebrow(kicker)}<h2>{title}</h2>{f"<p>{sub}</p>" if sub else ""}</div>'

hero_art='''<div class="hero-art" aria-label="Abstract engineering illustration inspired by a sun and robotic mechanism" role="img"><div class="art-fine-grid"></div><div class="art-index art-index--top">HLS / 5214<br>DESIGN SERIES 01</div><div class="orbit orbit--outer"></div><div class="orbit orbit--middle"></div><div class="orbit orbit--inner"></div><div class="orbit-mark mark-top"></div><div class="orbit-mark mark-right"></div><div class="orbit-mark mark-bottom"></div><div class="solar-core"><div class="solar-core-inner"><span class="core-top">FTC // HELIOS</span><strong>52<span>14</span></strong><span class="core-bottom">ENGINEER • ITERATE • REPEAT</span></div></div><div class="hero-art-chip"><span class="chip-sun"></span><span><strong>2026–27</strong><small>Current season / BIOBUZZ</small></span></div><div class="art-index art-index--bottom">DUBLIN, CA / 37°42′N</div></div>'''

home=f'''
<section class="hero section-block"><div class="container hero-layout"><div class="hero-copy">{eyebrow('DUBLIN, CALIFORNIA · FIRST TECH CHALLENGE')}<h1>Built with<br>curiosity.<br><em>Driven by</em> <span>sunshine.</span></h1><p>We’re Helios, FTC Team 5214. A student-driven robotics team turning big ideas into real machines—and bringing people along for the build.</p><div class="hero-actions">{link('/seasons/biobuzz/','Explore our season','dark')}{link('/team/','Meet the team','outline')}</div><div class="hero-note"><span class="tiny-star">✳</span><span>Engineering is better together.</span></div></div>{hero_art}</div></section>
<section class="stats-band"><div class="container stats-grid"><div><strong>16</strong><span>Seasons of FTC experience</span></div><div><strong>2010</strong><span>Our rookie year</span></div><div><strong>5214</strong><span>One team, many ideas</span></div><div><strong>Dublin</strong><span>California, USA</span></div></div></section>
<section class="section-block story-section"><div class="container story-grid"><div class="story-visual"><div class="story-visual-inner"><span class="visual-number">01 / THE TEAM</span><div class="visual-sun"><div class="visual-sun-center"></div></div><span class="visual-bottom">ALWAYS / IN PROGRESS</span></div><div class="corner-note">BUILD <span>→</span> LEARN <span>→</span> REBUILD</div></div><div class="story-text">{eyebrow('WHO WE ARE')}<h2>More than<br>the robot.</h2><p>We love the challenge of a competition. But for us, robotics is also about the people at the table: the ones sketching a mechanism, debugging a stubborn line of code, and asking what we could do better.</p><p>That spirit has carried Team 5214 through 16 seasons of FIRST Tech Challenge.</p>{link('/about/','Our story','text')}</div></div></section>
<section class="section-block seasons-preview"><div class="container"><div class="section-row">{section_intro('FROM THE WORKSHOP','Two seasons. <em>One continuous build.</em>','See where we are now and what we learned along the way.')}{link('/seasons/','All seasons','text')}</div><div class="feature-grid"><a class="feature-card feature-card--biobuzz" href="/seasons/biobuzz/"><div class="feature-card-head"><span>01 / CURRENT SEASON</span><span class="pill light-pill">IN PROGRESS <span class="pulse"></span></span></div><div class="season-graphic season-graphic--bee"><svg viewBox="0 0 280 180" fill="none" aria-hidden="true"><path d="M26 89h228M140 15v150" stroke="#F5D9A4" stroke-width="1" stroke-dasharray="4 6"/><circle cx="140" cy="90" r="64" stroke="#EFB653" stroke-width="1.5"/><circle cx="140" cy="90" r="39" stroke="#EFB653" stroke-width="1.5"/><path d="M103 74c0-19 16-34 35-34 9 0 18 4 24 10 6-6 14-10 23-10 15 0 27 12 27 27 0 17-16 28-50 45-33-17-50-29-50-45" stroke="#CB653C" stroke-width="3" stroke-linecap="round"/><path d="M111 95h69M119 108h53" stroke="#CB653C" stroke-width="6" stroke-linecap="round"/></svg></div><div class="feature-card-bottom"><small>2026—2027</small><h3>BIOBUZZ</h3><div class="feature-footer"><span>Designing what comes next</span>{arrow_diag}</div></div></a><a class="feature-card feature-card--decode" href="/seasons/decode/"><div class="feature-card-head"><span>02 / PREVIOUS SEASON</span><span class="pill">2025–26</span></div><div class="season-graphic season-graphic--decode"><svg viewBox="0 0 280 180" fill="none" aria-hidden="true"><circle cx="140" cy="90" r="65" stroke="#D7AB8A" stroke-width="1.5"/><circle cx="140" cy="90" r="42" stroke="#D7AB8A" stroke-width="1.5"/><path d="M95 46 185 136M185 46 95 136" stroke="#C46D4A" stroke-width="6" stroke-linecap="round"/><path d="M140 14v152M64 90h152" stroke="#D7AB8A" stroke-dasharray="3 6"/><rect x="115" y="65" width="50" height="50" rx="8" fill="#F5E7DD" stroke="#C46D4A" stroke-width="2"/><path d="M125 82h30m-30 10h30m-30 10h18" stroke="#C46D4A" stroke-width="3" stroke-linecap="round"/></svg></div><div class="feature-card-bottom"><small>2025—2026</small><h3>DECODE</h3><div class="feature-footer"><span>Innovate Award · East Bay</span>{arrow_diag}</div></div></a></div></div></section>
<section class="section-block impact-section"><div class="container impact-layout"><div>{eyebrow('BEYOND COMPETITION')}<h2>Pass the<br><em>spark</em> forward.</h2></div><div><p>Robotics is worth sharing. Through hands-on learning and community outreach, we hope to make science and engineering more approachable to the next generation of builders.</p>{link('/outreach/','Explore outreach','dark')}</div><span class="impact-big-sun" aria-hidden="true">✳</span></div></section>
<section class="closing-cta"><div class="container closing-inner"><div><span class="eyebrow">LET’S TALK ROBOTS</span><h2>Have an idea?<br>We’re all ears.</h2></div>{link('/contact/','Get in touch','light')}</div></section>
'''
page('Home','Helios FTC Team 5214 is a student-led robotics team in Dublin, California. Follow our robots, seasons, team, and outreach.', 'home',home)

about=f'''<section class="page-hero page-hero--about"><div class="container narrow-content">{eyebrow('ABOUT HELIOS / FTC 5214')}<h1>Experience makes<br>us better. <em>Curiosity</em><br>keeps us going.</h1><p>16 seasons of solving problems, working together, and learning through the process. That’s the story of Team 5214.</p></div><span class="page-hero-watermark">16</span></section>
<section class="section-block"><div class="container about-overview"><div>{eyebrow('OUR STORY')}<h2>Since 2010.<br>Still building.</h2></div><div class="readable"><p>Team 5214 began competing in FIRST Tech Challenge in 2010. Based in Dublin, California, we've been part of a program that asks students to think like engineers, collaborate as teammates, and learn by building something real.</p><p>Today, as Helios, we bring that history into every new challenge. Seasons change, designs evolve, and the team keeps learning.</p><a class="source-link" href="{TEAM_SOURCE}" target="_blank" rel="noopener noreferrer">View our official FIRST team record {arrow_diag}</a></div></div></section>
<section class="section-block timeline-section"><div class="container"><div class="section-row">{section_intro('MILESTONES','The journey <em>so far.</em>')}</div><div class="timeline"><div class="timeline-item"><div class="timeline-year">2010</div><div><strong>Where it started</strong><p>Team 5214’s rookie FTC season. The beginning of a long-running engineering journey.</p></div></div><div class="timeline-item"><div class="timeline-year">2023–24</div><div><strong>CENTERSTAGE</strong><p>Recognized with the Motivate Award at the East Bay League Tournament.</p></div></div><div class="timeline-item"><div class="timeline-year">2025–26</div><div><strong>DECODE</strong><p>Earned the Innovate Award at the East Bay League Tournament.</p></div></div><div class="timeline-item"><div class="timeline-year">2026–27</div><div><strong>BIOBUZZ</strong><p>Our current challenge. A new season to design, test, and grow.</p></div></div></div></div></section>
<section class="section-block philosophy-section"><div class="container"><div class="section-row">{section_intro('WHAT DRIVES US','How we approach <em>the work.</em>')}</div><div class="value-grid"><article><span>01</span><div class="value-icon">◎</div><h3>Think it through.</h3><p>Start with the problem. Ask good questions before reaching for a solution.</p></article><article><span>02</span><div class="value-icon">⌘</div><h3>Make it real.</h3><p>Turn sketches and plans into code, mechanisms, and working prototypes.</p></article><article><span>03</span><div class="value-icon">↗</div><h3>Keep improving.</h3><p>Test what we made, listen to feedback, and come back with something better.</p></article></div></div></section>
<section class="section-block small-cta"><div class="container small-cta-inner"><div>{eyebrow('MEET THE PEOPLE')}<h2>Every great robot takes a team.</h2></div>{link('/team/','Meet Helios','dark')}</div></section>'''
page('About','Learn about Helios FTC Team 5214, competing in FIRST Tech Challenge since 2010 and active for 16 seasons.', 'about',about,'/about/')

members=[('Bryan Pan','Captain','BP','01'),('Yuvan Ramesh','Software Lead','YR','02'),('Elan Jain','Business Lead','EJ','03'),('Damodar Kriplani','Driver / Media Lead','DK','04')]
member_cards=''.join(f'''<article class="member-card"><div class="member-photo" aria-label="Photo placeholder for {name}"><span class="photo-corner">{n} / TEAM 5214</span><div class="photo-monogram" aria-hidden="true">{initial}</div><span class="photo-caption">PHOTO COMING SOON</span></div><div class="member-card-bottom"><span class="member-role">{role.upper()}</span><h2>{name}</h2></div></article>''' for name,role,initial,n in members)
team=f'''<section class="page-hero page-hero--team"><div class="container narrow-content">{eyebrow('THE PEOPLE BEHIND 5214')}<h1>Different strengths.<br><em>One team.</em></h1><p>Meet the people bringing ideas, code, strategy, and energy to Helios.</p></div></section><section class="section-block team-section"><div class="container"><div class="team-topline"><span>OUR 2026–27 TEAM</span><span>04 MEMBERS / HELIOS</span></div><div class="member-grid">{member_cards}</div><div class="team-photo-note"><span class="info-symbol">i</span>Photo spaces are ready—replace each placeholder with a team member’s portrait when available.</div></div></section><section class="section-block team-bottom"><div class="container team-bottom-inner"><div>{eyebrow('MORE THAN ONE ROLE')}<h2>We show up for<br>each other.</h2></div><p>From the driver station to the code editor, everyone has a part in building something that works. Collaboration is what brings the pieces together.</p></div></section>'''
page('Our Team','Meet Helios Team 5214: Bryan Pan, Yuvan Ramesh, Elan Jain, and Damodar Kriplani.', 'team',team,'/team/')

outreach=f'''<section class="page-hero page-hero--outreach"><div class="container narrow-content">{eyebrow('HELIOS IN THE COMMUNITY')}<h1>Good ideas are<br>meant to be <em>shared.</em></h1><p>We build robots for competition. We share what we learn because the next great engineer could be anywhere.</p></div></section><section class="section-block"><div class="container outreach-intro"><div>{eyebrow('WHY IT MATTERS')}<h2>Making room for<br>more makers.</h2></div><div class="readable"><p>We believe an introduction to STEM can begin with something simple: a question, a small experiment, or a chance to try. Our outreach is about making that first step welcoming and hands-on.</p><p>As our projects develop, this space will document the activities, lessons, and people behind them.</p></div></div></section><section class="section-block outreach-projects"><div class="container"><div class="section-row">{section_intro('COMMUNITY INITIATIVES','A spark that <em>travels.</em>')}</div><div class="outreach-feature"><div class="outreach-graphic"><span class="outreach-graphic-label">OUTREACH NOTEBOOK / 001</span><div class="kit-illustration"><span class="kit-node">01</span><span class="kit-wire"></span><span class="kit-node">02</span><span class="kit-wire"></span><span class="kit-node">03</span></div><span class="outreach-graphic-bottom">LEARN / BUILD / EXPLORE</span></div><div class="outreach-feature-copy"><span class="eyebrow">FEATURED INITIATIVE</span><h3>IntelliKits</h3><p>Hands-on STEM learning is at the center of IntelliKits, a Helios initiative designed to introduce younger learners to technology and robotics concepts in an approachable way.</p><p class="muted-small">Project photos and activity highlights can be added here as the team documents its work.</p>{link('/contact/','Partner with us','text')}</div></div><div class="outreach-pillars"><article><span>01 / DEMONSTRATE</span><h3>Show, don’t just tell.</h3><p>Make engineering tangible through demonstrations and hands-on exploration.</p></article><article><span>02 / CONNECT</span><h3>Invite new perspectives.</h3><p>Create opportunities to ask questions, try ideas, and learn together.</p></article><article><span>03 / INSPIRE</span><h3>Keep the spark going.</h3><p>Encourage students to see themselves as future makers and problem-solvers.</p></article></div></div></section><section class="closing-cta"><div class="container closing-inner"><div><span class="eyebrow">WORK WITH HELIOS</span><h2>Let’s make<br>something meaningful.</h2></div>{link('/contact/','Connect with us','light')}</div></section>'''
page('Outreach','Discover Helios FTC Team 5214 community outreach, STEM learning and the IntelliKits initiative.', 'outreach',outreach,'/outreach/')

archive=''.join(f'<a href="{url}" target="_blank" rel="noopener noreferrer"><span class="archive-year">{year}</span><strong>{name}</strong><span class="archive-tag">FIRST RECORD</span>{arrow_diag}</a>' for year,name,url in seasons[2:])
seasons_page=f'''<section class="page-hero page-hero--seasons"><div class="container narrow-content">{eyebrow('FROM FIRST SKETCH TO FINAL MATCH')}<h1>Every season,<br>a new <em>challenge.</em></h1><p>Look closer at our recent seasons—and explore the years that brought Team 5214 here.</p></div></section><section class="section-block"><div class="container"><div class="season-main-grid"><a class="season-main-card current" href="/seasons/biobuzz/"><span class="season-card-kicker">2026–2027 <span class="season-status">CURRENT SEASON</span></span><div class="season-main-center"><span class="giant-season-index">01</span><h2>BIOBUZZ</h2><p>New game. New questions. New ideas on the workbench.</p></div><span class="season-card-bottom">Explore the season {arrow_diag}</span></a><a class="season-main-card past" href="/seasons/decode/"><span class="season-card-kicker">2025–2026 <span>PREVIOUS SEASON</span></span><div class="season-main-center"><span class="giant-season-index">02</span><h2>DECODE</h2><p>An Innovate Award and a season of design, iteration, and competition.</p></div><span class="season-card-bottom">Explore the season {arrow_diag}</span></a></div></div></section><section class="section-block archive-section"><div class="container"><div class="archive-heading">{section_intro('THROUGH THE YEARS','The season <em>archive.</em>','Earlier seasons link to Team 5214’s verified results on the official FIRST events website.')}</div><div class="archive-list">{archive}</div><p class="archive-note">Official historical records may list a previous team name for the same team number.</p></div></section>'''
page('Seasons','Explore Helios FTC Team 5214 seasons including 2026–27 BIOBUZZ, 2025–26 DECODE, and the FIRST events history.', 'seasons',seasons_page,'/seasons/')

biobuzz=f'''<section class="season-detail-hero biobuzz-detail"><div class="container"><a href="/seasons/" class="back-link">← ALL SEASONS</a><div class="detail-hero-layout"><div>{eyebrow('2026–2027 / CURRENT SEASON')}<h1>BIO<span>BUZZ.</span></h1><p>A new season is underway. We’re here to experiment, make mistakes, learn fast, and turn what we discover into a machine ready for competition.</p><span class="pill detail-status"><span class="pulse"></span> WORK IN PROGRESS</span></div><div class="detail-illustration" aria-label="Abstract BIOBUZZ season artwork" role="img"><div class="honeycomb honey-1"></div><div class="honeycomb honey-2"></div><div class="honeycomb honey-3"></div><div class="honeycomb honey-4"></div><span>26<br><em>27</em></span></div></div></div></section><section class="section-block"><div class="container detail-overview"><div>{eyebrow('SEASON JOURNAL')}<h2>The next chapter<br>is being written.</h2></div><div class="readable"><p>BIOBUZZ is the 2026–27 FIRST Tech Challenge game. Our team’s robot, engineering process, and competition updates will take shape throughout the season.</p><p>We’ll keep the public-facing record here focused on milestones that are ready to share rather than posting unverified results.</p><a class="source-link" href="https://ftc-resources.firstinspires.org/ftc/game" target="_blank" rel="noopener noreferrer">Official BIOBUZZ season resources {arrow_diag}</a></div></div></section><section class="section-block update-grid-wrap"><div class="container"><div class="section-row">{section_intro('WHAT WE’RE WORKING ON','The journey <em>ahead.</em>')}</div><div class="update-grid"><article><span>01 / ROBOT</span><h3>Design & build</h3><p>Robot photos, mechanisms, and engineering notes will be added as our design develops.</p></article><article><span>02 / SOFTWARE</span><h3>Code & control</h3><p>Look here for future programming highlights, automation work, and lessons learned.</p></article><article><span>03 / EVENTS</span><h3>Competition log</h3><p>Verified event results will be added once they are available on FIRST.</p></article></div></div></section><div class="container next-season-link"><a href="/seasons/decode/"><span>PREVIOUS SEASON</span><strong>2025–26 / DECODE</strong>{arrow_diag}</a></div>'''
